// Builds supabase/seed.sql from the sample trips in trips.js.
// Run: node supabase/make-seed.js
const fs = require("fs");
const path = require("path");
const vm = require("vm");

const src = fs.readFileSync(path.join(__dirname, "..", "trips.js"), "utf8");
const ctx = { localStorage: { getItem: () => null } }; // trips.js reads published trips from the browser
vm.createContext(ctx);
vm.runInContext(src + "\nthis.TRIPS = TRIPS;", ctx);

const q = s => "'" + String(s).replace(/'/g, "''") + "'";
const lines = [
  "-- Sample trips for TrailPeak. Generated by supabase/make-seed.js from trips.js; don't edit by hand.",
  "-- Safe to run again: it replaces the sample trips and their dates.",
  "delete from public.trips where organizer_id is null;",
  "",
];
for (const t of ctx.TRIPS) {
  const { departures, ...details } = t;
  lines.push(`insert into public.trips (id, organizer_id, org_name, details) values (${q(t.id)}, null, ${q(t.org)}, $json$${JSON.stringify(details)}$json$::jsonb);`);
  for (const [date, left] of Object.entries(departures)) {
    lines.push(`insert into public.departures (trip_id, date, capacity, sample_booked) values (${q(t.id)}, ${q(date)}, ${t.group}, ${t.group - left});`);
  }
  lines.push("");
}
fs.writeFileSync(path.join(__dirname, "seed.sql"), lines.join("\n"));
console.log(`Wrote seed.sql: ${ctx.TRIPS.length} trips`);
